WITH matched_keys AS (SELECT store_id, product_id FROM store_sales EXCEPT ALL SELECT store_id, product_id FROM store_sales WHERE revenue < 2900), verified AS (SELECT s.* FROM store_sales s JOIN matched_keys k ON s.store_id = k.store_id AND s.product_id = k.product_id) SELECT s.id, s.store_id, s.product_id, s.sale_date, s.revenue, (SELECT SUM(x.revenue) FROM store_sales x WHERE x.store_id = s.store_id) AS sum_store_sale_revenue FROM verified s ORDER BY product_id DESC NULLS FIRST
